import { chromium } from "playwright-core";
const out = "/workspace/hermes-mobile/dist/screens";
const b = await chromium.launch({ executablePath: "/opt/google/chrome/chrome", args: ["--no-sandbox"] });
const p = await (await b.newContext({ viewport: { width: 412, height: 915 }, deviceScaleFactor: 2 })).newPage();
const errs = []; p.on("pageerror", (e) => errs.push(String(e)));
await p.goto("http://localhost:8799/"); await p.waitForTimeout(2500);
const vis = (l) => p.getByLabel(l, { exact: true }).filter({ visible: true }).first();
console.log("CF fields visible while collapsed:", await p.getByLabel("Cloudflare Access Client ID", { exact: true }).filter({ visible: true }).count());
await p.screenshot({ path: `${out}/17-settings-funnel.png` });
await vis("Cloudflare Access (optional)").click(); await p.waitForTimeout(400);
console.log("CF fields visible after expand:", await p.getByLabel("Cloudflare Access Client ID", { exact: true }).filter({ visible: true }).count());
await p.screenshot({ path: `${out}/17-settings-cf-expanded.png` });
await vis("Cloudflare Access (optional)").click(); await p.waitForTimeout(300);
await vis("Server URL").fill("homelab.tail0000.ts.net/");
await vis("Hermes API key").fill("bogus-key");
const sent = [];
p.on("request", (r) => { if (r.url().includes("ts.net")) sent.push(r.headers()); });
await p.getByText("Test & save").click(); await p.waitForTimeout(4000);
console.log("url normalized:", await vis("Server URL").inputValue());
console.log("request had CF headers:", sent.some((h) => "cf-access-client-id" in h), "auth:", sent[0]?.authorization);
console.log("error:", (await p.locator("text=/Can't reach|refused|Reached/").allInnerTexts()).slice(-1));
await p.screenshot({ path: `${out}/17-settings-test-failed.png` });
await p.getByText("Save anyway (test later)").click(); await p.waitForTimeout(5000);
console.log("offline:", (await p.locator("body").innerText()).replace(/\s+/g, " ").slice(0, 120));
console.log("pageerrors:", errs.length, errs.slice(0, 2));
await b.close();
